import os
import shutil
from datetime import datetime


_BACKED_UP_PATHS = set()


def _backup_name(path: str) -> str:
    base_name = os.path.basename(os.path.expanduser(path)) or "config"
    name, ext = os.path.splitext(base_name)
    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    return f"{name}-{timestamp}{ext}.bak"


def backup_existing_file(path: str, display_name: str = None, new_content: str = None) -> str:
    source = os.path.expanduser(path)
    if not os.path.exists(source):
        return ""

    if new_content is not None:
        try:
            with open(source, "r", encoding="utf-8") as f:
                if f.read() == new_content:
                    return ""
        except UnicodeDecodeError:
            pass

    real_source = os.path.abspath(source)
    if real_source in _BACKED_UP_PATHS:
        return ""

    source_dir = os.path.dirname(real_source) or os.getcwd()
    backup_dir = os.path.join(source_dir, "back", "auto++")
    os.makedirs(backup_dir, exist_ok=True)
    backup_path = os.path.join(backup_dir, _backup_name(real_source))
    counter = 1
    while os.path.exists(backup_path):
        root, ext = os.path.splitext(backup_path)
        backup_path = f"{root}-{counter}{ext}"
        counter += 1

    shutil.copy2(real_source, backup_path)
    _BACKED_UP_PATHS.add(real_source)

    name = display_name or os.path.basename(source) or source
    print(f"已备份 {name}: {backup_path}")
    return backup_path
